for (const language of ["fr", "it", "ja"] as const) {
  const labels = compactLanguageLabels[language];
  const slugs = ["agent-invented-humans-malware-github", "vibe-hacking-data-extortion", "ai-orchestrated-cyber-espionage"];
  slugs.forEach((slug, index) => {
    compactTranslations[language][slug] = {
      title: labels.titles[index], shortTitle: labels.shorts[index], kicker: labels.kickers[index], excerpt: labels.excerpts[index], conduct: labels.conduct[index], autonomy: labels.autonomy[index], status: labels.status[index], headings: labels.headings[index], summaries: labels.summaries[index], metricLabels: labels.metrics[index],
    };
  });
}

export function localizeAICrimeCase(item: AICrimeCase, language: AICrimeLanguage): AICrimeCase {
  if (language === "en") return item;
  const full = localizedCases[language][item.slug];
  if (full) return { ...item, ...full };
  const compact = compactTranslations[language as Exclude<AICrimeLanguage, "en" | "pt">]?.[item.slug];
  if (!compact) return item;
  return {
    ...item,
    title: compact.title,
    shortTitle: compact.shortTitle,
    kicker: compact.kicker,
    excerpt: compact.excerpt,
    published: compactDates[language as Exclude<AICrimeLanguage, "en" | "pt">].published,
    eventDate: compactDates[language as Exclude<AICrimeLanguage, "en" | "pt">].events[item.slug],
    criminalConduct: compact.conduct,
    autonomy: compact.autonomy,
    legalStatus: compact.status,
    metrics: item.metrics.map((metric, index) => ({ ...metric, label: compact.metricLabels[index] ?? metric.label })),
    sections: item.sections.map((section, index) => ({
      heading: compact.headings[index] ?? section.heading,
      paragraphs: [compact.summaries[index] ?? section.paragraphs.join(" ")],
    })),
  };
}

export function localizeAICrimeCases(items: AICrimeCase[], language: AICrimeLanguage) {
  return items.map((item) => localizeAICrimeCase(item, language));
}
